$('adaptiveDiscard').onclick=()=>{clearAdaptive();action('Proposal discarded; target and background points remain. Accepted mask unchanged.');};
$('adaptiveClear').onclick=()=>{const oldPositive=adaptivePositive,oldNegative=adaptiveNegative;clearAdaptivePoints();if(oldPositive.length||oldNegative.length)recordAction({undo(){adaptivePositive=oldPositive;adaptiveNegative=oldNegative;},redo(){adaptivePositive=[];adaptiveNegative=[];}});action('Target and background points cleared; accepted mask unchanged.');};
function scan(files,isDirectory=false){inputGate.begin();if(!files.length)return;clearVolume();worker?.terminate();worker=new Worker('./io-worker.js?v=0.7.10');const current=worker,input=describeInput(files,isDirectory);status('Сканирование · '+input);$('series').hidden=$('load').hidden=true;worker.onerror=e=>{if(worker===current)status('Worker failure ('+input+'): '+e.message);};worker.onmessage=({data})=>{if(worker!==current)return;if(data.type==='error'){status('Measurement blocked [v0.7.10; '+input+']: '+data.message);return;}if(data.type==='groups'){const select=$('series');select.replaceChildren(...data.groups.map(g=>{const o=document.createElement('option');o.value=g.key;o.textContent=g.name+' · '+g.modality+' · '+g.frames+' slices · '+g.dims.join('×');return o;}));if(data.groups.length===1){select.hidden=$('load').hidden=true;status('One series found · decoding full image stack…');worker.postMessage({type:'build',key:data.groups[0].key});}else{select.hidden=$('load').hidden=false;status('Choose a series ('+data.groups.length+' found; '+data.skipped+' skipped).');}}if(data.type==='volume')setVolume(data.volume);if(data.type==='progress')status(data.text+' '+Math.round(data.fraction*100)+'%');};worker.postMessage({type:'scan',slot:'ct',files:Array.from(files)});}
$('files').onchange=e=>scan(e.target.files);$('folder').onchange=e=>scan(e.target.files,true);$('load').onclick=()=>{if(!worker)return;clearVolume();status('Decoding full image stack…');worker.postMessage({type:'build',key:$('series').value});};
document.addEventListener('dragover',e=>e.preventDefault());
document.addEventListener('drop',async e=>{
 e.preventDefault();const token=inputGate.begin();
 worker?.terminate();worker=null;clearVolume();$('series').hidden=$('load').hidden=true;status('Reading dropped input…');
 try{const isDirectory=Array.from(e.dataTransfer.items||[]).some(item=>item.webkitGetAsEntry?.()?.isDirectory),awaitedFiles=await filesFromDrop(e.dataTransfer);if(inputGate.current(token))scan(awaitedFiles,isDirectory);}
 catch(error){if(inputGate.current(token))status('Не удалось прочитать перетащенную папку: '+error.message);}
});
